"""
Data produced by one crypto backend must be accepted by the other one, in both directions.
"""

import os
import random

import pytest

import _crypto_test_vectors as vectors
from conftest import import_crypto_backend

PLAINTEXT_LENGTHS = [0, 1, 15, 16, 17, 1000]
PASSPHRASES = [None, b"some passphrase", "sömé passphrâse"]


@pytest.fixture(scope="module")
def keypairs(both_backends):
    """Keypairs generated by each backend, as {(backend_index, key_type): (public_key, private_key)}"""
    keypairs = {}
    for index, backend in enumerate(both_backends):
        keypairs[(index, "RSA")] = backend.generate_rsa_keypair(2048)
        keypairs[(index, "DSA")] = backend.generate_dsa_keypair(2048)
        keypairs[(index, "X25519")] = backend.generate_ecc_keypair("curve25519")
    return keypairs


def _directions(both_backends):
    native, fallback = both_backends
    return [(native, fallback), (fallback, native)]


def _transfer_key(source, destination, key_type, key, passphrase=None):
    """Export a key from one backend, and import it into the other one."""
    export = dict(RSA=source.export_rsa_key_to_pem, DSA=source.export_dsa_key_to_pem, X25519=source.export_ecc_key_to_pem)
    import_ = dict(
        RSA=destination.import_rsa_key_from_pem,
        DSA=destination.import_dsa_key_from_pem,
        X25519=destination.import_ecc_key_from_pem,
    )
    return import_[key_type](export[key_type](key, passphrase=passphrase), passphrase=passphrase)


def _hash_sha512(backend, message):
    hasher = backend.get_hasher_instance("SHA512")
    hasher.update(message)
    return hasher


def _flip_last_bit(data):
    return data[:-1] + bytes([data[-1] ^ 1])


@pytest.mark.parametrize("length", PLAINTEXT_LENGTHS)
def test_symmetric_ciphers(both_backends, length):
    native, fallback = both_backends
    key, plaintext = os.urandom(32), os.urandom(length)
    iv, eax_nonce, chacha_nonce = os.urandom(16), os.urandom(16), os.urandom(12)

    ciphertext = native.encrypt_via_aes_cbc(plaintext, key=key, iv=iv)
    assert fallback.encrypt_via_aes_cbc(plaintext, key=key, iv=iv) == ciphertext
    for backend in both_backends:
        assert backend.decrypt_via_aes_cbc(ciphertext, key=key, iv=iv) == plaintext

    for encrypt_name, decrypt_name, nonce in [
        ("encrypt_via_aes_eax", "decrypt_via_aes_eax", eax_nonce),
        ("encrypt_via_chacha20_poly1305", "decrypt_via_chacha20_poly1305", chacha_nonce),
    ]:
        ciphertext, tag = getattr(native, encrypt_name)(plaintext, key=key, nonce=nonce)
        assert getattr(fallback, encrypt_name)(plaintext, key=key, nonce=nonce) == (ciphertext, tag)
        for backend in both_backends:
            decrypt = getattr(backend, decrypt_name)
            assert decrypt(ciphertext, tag, key=key, nonce=nonce, verify_integrity_tags=True) == plaintext
            with pytest.raises(ValueError):  # Tampering is detected by both backends
                decrypt(ciphertext, _flip_last_bit(tag), key=key, nonce=nonce, verify_integrity_tags=True)
            if ciphertext:
                with pytest.raises(ValueError):
                    decrypt(_flip_last_bit(ciphertext), tag, key=key, nonce=nonce, verify_integrity_tags=True)


def _feed_in_random_chunks(cipher, data, block_size=1):
    cuts = sorted(random.randint(0, len(data) // block_size) * block_size for _ in range(2))
    chunks = [data[: cuts[0]], memoryview(data)[cuts[0] : cuts[1]], data[cuts[1] :]]
    return b"".join(cipher.encrypt(chunk) for chunk in chunks)


@pytest.mark.parametrize("length", PLAINTEXT_LENGTHS)
def test_streaming_encryption(both_backends, length):
    from wacryptolib.utilities import pad_bytes_pkcs7

    key, plaintext = os.urandom(32), os.urandom(length)
    iv, eax_nonce, chacha_nonce = os.urandom(16), os.urandom(16), os.urandom(12)

    for source, destination in _directions(both_backends):
        cipher = source.build_aes_cbc_encrypter(key, iv=iv)
        ciphertext = _feed_in_random_chunks(cipher, pad_bytes_pkcs7(plaintext, block_size=16), block_size=16)
        assert not hasattr(cipher, "finalize")  # Else EncryptionNodeBase would append its output
        assert ciphertext == destination.encrypt_via_aes_cbc(plaintext, key=key, iv=iv)

        for builder_name, encrypt_name, nonce in [
            ("build_aes_eax_cipher", "encrypt_via_aes_eax", eax_nonce),
            ("build_chacha20_poly1305_cipher", "encrypt_via_chacha20_poly1305", chacha_nonce),
        ]:
            cipher = getattr(source, builder_name)(key, nonce=nonce)
            ciphertext = _feed_in_random_chunks(cipher, plaintext)
            assert (ciphertext, cipher.digest()) == getattr(destination, encrypt_name)(plaintext, key=key, nonce=nonce)


def test_rsa_oaep(both_backends, keypairs):
    for index, (source, destination) in enumerate(_directions(both_backends)):
        public_key, private_key = keypairs[(index, "RSA")]
        plaintext_chunks = [b"", b"x", os.urandom(126)]  # RSA_OAEP_CHUNKS_SIZE is 60, with 2048 bits keys
        ciphertext_chunks = destination.encrypt_via_rsa_oaep(
            plaintext_chunks, _transfer_key(source, destination, "RSA", public_key)
        )
        assert source.decrypt_via_rsa_oaep(ciphertext_chunks, private_key) == plaintext_chunks
        with pytest.raises(ValueError):
            source.decrypt_via_rsa_oaep([_flip_last_bit(ciphertext_chunks[0])], private_key)


def test_rsa_oaep_with_cryptography_as_third_reference(both_backends):
    rsa = pytest.importorskip("cryptography.hazmat.primitives.asymmetric.rsa")
    from cryptography.hazmat.primitives import hashes, serialization
    from cryptography.hazmat.primitives.asymmetric import padding

    oaep_padding = padding.OAEP(mgf=padding.MGF1(algorithm=hashes.SHA512()), algorithm=hashes.SHA512(), label=None)
    private_key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
    private_key_pem = private_key.private_bytes(
        serialization.Encoding.PEM, serialization.PrivateFormat.TraditionalOpenSSL, serialization.NoEncryption()
    )
    public_key_pem = private_key.public_key().public_bytes(
        serialization.Encoding.PEM, serialization.PublicFormat.SubjectPublicKeyInfo
    )
    for backend in both_backends:
        ciphertext = private_key.public_key().encrypt(b"abc", oaep_padding)
        assert backend.decrypt_via_rsa_oaep([ciphertext], backend.import_rsa_key_from_pem(private_key_pem)) == [b"abc"]
        (ciphertext,) = backend.encrypt_via_rsa_oaep([b"abc"], backend.import_rsa_key_from_pem(public_key_pem))
        assert private_key.decrypt(ciphertext, oaep_padding) == b"abc"


def test_hpke(both_backends, keypairs):
    aead_id = 0x0003  # ChaCha20-Poly1305, used by ECIES_X25519
    for index, (source, destination) in enumerate(_directions(both_backends)):
        public_key, private_key = keypairs[(index, "X25519")]
        for plaintext in (b"", b"abc", os.urandom(300)):
            enc, ciphertext = destination.encrypt_via_hpke(
                plaintext, _transfer_key(source, destination, "X25519", public_key), aead_id=aead_id
            )
            assert source.decrypt_via_hpke(enc, ciphertext, private_key, aead_id=aead_id) == plaintext
            with pytest.raises(ValueError, match="wrong MAC tag"):  # Same message, see wacryptolib.cipher
                source.decrypt_via_hpke(enc, _flip_last_bit(ciphertext), private_key, aead_id=aead_id)


@pytest.mark.parametrize("passphrase", PASSPHRASES)
@pytest.mark.parametrize("key_type", ["RSA", "DSA", "X25519"])
def test_pem_keys(both_backends, keypairs, key_type, passphrase):
    for index, (source, destination) in enumerate(_directions(both_backends)):
        public_key, private_key = keypairs[(index, key_type)]
        transferred_public_key = _transfer_key(source, destination, key_type, public_key)
        transferred_private_key = _transfer_key(source, destination, key_type, private_key, passphrase=passphrase)

        # Clear PEM exports are byte-identical, whatever the backend
        roundtrip_public_key = _transfer_key(destination, source, key_type, transferred_public_key)
        roundtrip_private_key = _transfer_key(destination, source, key_type, transferred_private_key)
        for original_key, roundtrip_key in [(public_key, roundtrip_public_key), (private_key, roundtrip_private_key)]:
            export = dict(RSA=source.export_rsa_key_to_pem, DSA=source.export_dsa_key_to_pem, X25519=source.export_ecc_key_to_pem)[key_type]
            assert export(roundtrip_key) == export(original_key)

        # Transferred keys work with the destination backend
        if key_type == "RSA":
            (ciphertext,) = destination.encrypt_via_rsa_oaep([b"abc"], transferred_public_key)
            assert destination.decrypt_via_rsa_oaep([ciphertext], transferred_private_key) == [b"abc"]
        elif key_type == "DSA":
            hasher = _hash_sha512(destination, b"abc")
            signature = destination.sign_with_dss(hasher, transferred_private_key)
            destination.verify_with_dss(hasher, signature, transferred_public_key)
        else:
            enc, ciphertext = destination.encrypt_via_hpke(b"abc", transferred_public_key, aead_id=0x0003)
            assert destination.decrypt_via_hpke(enc, ciphertext, transferred_private_key, aead_id=0x0003) == b"abc"


@pytest.mark.parametrize("key_type", sorted(vectors.PYCRYPTODOME_PEM_FIXTURES))
def test_pycryptodome_pem_fixtures(backend, key_type):
    """Also run without pycryptodome, to check the fallback backend against PEMs made by pycryptodome."""
    fixture = vectors.PYCRYPTODOME_PEM_FIXTURES[key_type]
    passphrase = vectors.PYCRYPTODOME_PEM_FIXTURES_PASSPHRASE
    import_ = dict(RSA=backend.import_rsa_key_from_pem, DSA=backend.import_dsa_key_from_pem, X25519=backend.import_ecc_key_from_pem)[key_type]
    export = dict(RSA=backend.export_rsa_key_to_pem, DSA=backend.export_dsa_key_to_pem, X25519=backend.export_ecc_key_to_pem)[key_type]
    _as_bytes = lambda pem: pem if isinstance(pem, bytes) else pem.encode("ascii")  # noqa: E731

    for field in ("public_key", "private_key"):
        assert _as_bytes(export(import_(fixture[field]))) == fixture[field]
    for field in ("encrypted_private_key", "legacy_encrypted_private_key"):
        if field in fixture:
            assert _as_bytes(export(import_(fixture[field], passphrase=passphrase))) == fixture["private_key"]
            with pytest.raises(ValueError):
                import_(fixture[field], passphrase=b"wrong passphrase")


@pytest.mark.parametrize("key_type", ["RSA", "DSA"])
def test_signatures(both_backends, keypairs, key_type):
    sign_name, verify_name = dict(RSA=("sign_with_pss", "verify_with_pss"), DSA=("sign_with_dss", "verify_with_dss"))[key_type]
    for index, (source, destination) in enumerate(_directions(both_backends)):
        public_key, private_key = keypairs[(index, key_type)]
        signature = getattr(source, sign_name)(_hash_sha512(source, b"some message"), private_key)
        transferred_public_key = _transfer_key(source, destination, key_type, public_key)
        verify = getattr(destination, verify_name)
        verify(_hash_sha512(destination, b"some message"), signature, transferred_public_key)
        with pytest.raises(ValueError):
            verify(_hash_sha512(destination, b"some message"), _flip_last_bit(signature), transferred_public_key)
        with pytest.raises(ValueError):
            verify(_hash_sha512(destination, b"other message"), signature, transferred_public_key)


def test_both_backends_are_tested_in_main_environment():
    # Fails loudly, rather than letting all interop tests be skipped, when pycryptodome is installed
    pytest.importorskip("Crypto.Cipher.AES")
    import_crypto_backend("pycryptodome")
    from wacryptolib._crypto_backend import fallback  # noqa: F401 ("fallbacks" extra must be installed for tests)
